mapper.select:
/* Notiset01Mapper.selectMySettings */
SELECT
      NOTI_TYPE  AS notiType
    , USE_YN     AS useYn
  FROM TB_USER_PUSH_SETTING
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}

mapper.insert:
/* Notiset01Mapper.upsertSetting */
INSERT INTO TB_USER_PUSH_SETTING (
      CMPNY_CD
    , USER_CD
    , NOTI_TYPE
    , USE_YN
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{cmpnyCd}
    , #{userCd}
    , #{notiType}
    , #{useYn}
    , #{actor}
    , NOW()
)
ON DUPLICATE KEY UPDATE
      USE_YN      = #{useYn}
    , UPDATE_NO   = #{actor}
    , UPDATE_DATE = NOW()

mapper.select:
/* Notiset01Mapper.existsNodeAdminAnySite */
SELECT EXISTS(
    SELECT 1
      FROM TB_SITE_NODE
     WHERE CMPNY_CD = #{cmpnyCd}
       AND ( MAIN_ADMIN_CD = #{userCd} OR SUB_ADMIN_CD = #{userCd} )
)
